import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type {
  Alert,
  AlertKind,
  Config,
  InspectState,
  LedgerEntry,
  Level,
  ProjectMap,
  RecentCall,
  Route,
  Tab,
  TaskStatus,
  Usage,
} from '../types'
import { chars, protectedIds, restore } from './lib/guard'
import { checklist, editedFile, isUiFile, isVisualCheck } from './lib/inspect'
import {
  asMap,
  bar,
  brief,
  EMPTY_MAP,
  fromTodos,
  MAP_PROMPT,
  MAP_SCHEMA,
  mergeMap,
  progress,
} from './lib/map'
import { ARCHITECT_PROMPT, levelOf } from './lib/route'
import { freshLoop, observe, signature } from './lib/stuck'
import type { Loop } from './lib/stuck'

const PANE = 'cockpit'
const MAP_TOOL = 'mcp__cockpit__map'
const MAIN = 'main'
const STALL_CHECK_MS = 30_000

const DEFAULTS: Config = {
  guard: true,
  stuck: true,
  inspect: true,
  architect: false,
  map: true,
  meter: true,
  repeatLimit: 3,
  errorLimit: 4,
  stallMinutes: 5,
  models: { easy: 'haiku', medium: 'sonnet', hard: 'opus' },
  rules: [],
}

const NO_INSPECTION: InspectState = { pending: [], lastCheck: '', nudges: 0 }

const tab = atom({ plugin: 'cockpit', key: 'tab' } as const, 'home')
const config = atom({ plugin: 'cockpit', key: 'config' } as const, DEFAULTS)
const pins = atom({ plugin: 'cockpit', key: 'pins' } as const, [])
const recent = atom({ plugin: 'cockpit', key: 'recent' } as const, [])
const ledger = atom({ plugin: 'cockpit', key: 'ledger' } as const, [])
const map = atom({ plugin: 'cockpit', key: 'map' } as const, EMPTY_MAP)
const alerts = atom({ plugin: 'cockpit', key: 'alerts' } as const, [])
const routes = atom({ plugin: 'cockpit', key: 'routes' } as const, [])
const inspect = atom({ plugin: 'cockpit', key: 'inspect' } as const, NO_INSPECTION)
const usage = atom({ plugin: 'cockpit', key: 'usage' } as const, {})

const TABS: readonly { id: Tab; label: string }[] = [
  { id: 'home', label: 'Home' },
  { id: 'compact', label: 'Compact' },
  { id: 'map', label: 'Map' },
  { id: 'stuck', label: 'Stuck' },
  { id: 'inspect', label: 'Inspect' },
  { id: 'architect', label: 'Architect' },
]

const FEATURES: readonly {
  key: 'guard' | 'stuck' | 'inspect' | 'architect' | 'map' | 'meter'
  label: string
  about: string
}[] = [
  { key: 'guard', label: 'Compact guard', about: 'pins and rules survive compaction' },
  { key: 'stuck', label: 'Stuck detector', about: 'loops, error streaks, thrashing, stalls' },
  { key: 'inspect', label: 'Pixel inspector', about: 'UI edits need a screenshot check' },
  { key: 'architect', label: 'Architect', about: 'plan, delegate by difficulty, review' },
  { key: 'map', label: 'Project map', about: 'goal, tasks and decisions, kept per project' },
  { key: 'meter', label: 'Token meter', about: 'tokens per model in the status line' },
]

const MODELS = ['haiku', 'sonnet', 'opus', 'inherit'].map(value => ({ value }))
const LEVELS: readonly Level[] = ['easy', 'medium', 'hard']
const NEXT_STATUS: Record<TaskStatus, TaskStatus> = {
  todo: 'doing',
  doing: 'done',
  done: 'todo',
  blocked: 'doing',
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function options(values: readonly number[]): { value: string }[] {
  return values.map(value => ({ value: String(value) }))
}

function short(text: string, limit: number): string {
  return text.length <= limit ? text : `${text.slice(0, Math.max(0, limit - 1))}…`
}

function thousands(count: number): string {
  return count < 1000 ? String(count) : `${(count / 1000).toFixed(1)}k`
}

function preview(args: Record<string, unknown>): string {
  const main = args.file_path ?? args.command ?? args.pattern ?? args.url ?? args.description
  const text = typeof main === 'string' ? main : (JSON.stringify(args) ?? '')

  return short(text.replace(/\s+/g, ' '), 60)
}

function loadConfig(saved: unknown): Config {
  if (!isRecord(saved)) {
    return DEFAULTS
  }
  const models = isRecord(saved.models) ? saved.models : {}

  return {
    ...DEFAULTS,
    ...saved,
    models: { ...DEFAULTS.models, ...models },
    rules: Array.isArray(saved.rules)
      ? saved.rules.filter((rule): rule is string => typeof rule === 'string')
      : [],
  } as Config
}

async function setConfig($: EngineInterface, change: (held: Config) => Config): Promise<void> {
  await update($, config, change)
  await $.store.set('config', await read($, config))
}

async function setMap(
  $: EngineInterface,
  change: (held: ProjectMap) => ProjectMap,
): Promise<ProjectMap> {
  await update($, map, change)
  const held = await read($, map)
  await $.store.set(`map:${await $.session.root()}`, held)

  return held
}

async function raise($: EngineInterface, kind: AlertKind, text: string): Promise<void> {
  const alert: Alert = { at: await $.clock.now(), kind, text }
  await update($, alerts, list => [...list, alert].slice(-30))
  $.ui.toast(short(text, 160), { timeoutMs: 10_000 })
}

function meterLine(totals: Usage): string | undefined {
  const models = Object.keys(totals)
  if (models.length === 0) {
    return undefined
  }
  let input = 0
  let output = 0
  for (const model of models) {
    input += totals[model]?.input ?? 0
    output += totals[model]?.output ?? 0
  }

  return `cockpit ${thousands(input)} in / ${thousands(output)} out`
}

export const register: Register = on => {
  // Counters a reload may lose: they only pace alerts within one turn.
  const loops = new Map<string, Loop>()
  let isTurnRunning = false
  let lastActivity = 0
  let hasStalled = false
  let isBriefed = false

  on('session.start', async ($, e, next) => {
    const saved = loadConfig(await $.store.get('config'))
    await update($, config, () => saved)
    const stored = asMap(await $.store.get(`map:${await $.session.root()}`))
    await update($, map, () => stored)

    await $.command.register({
      name: 'cockpit',
      description: 'Open the Cockpit pane: compaction, routing, map, stuck and UI checks',
    })
    await $.tool.register({
      name: 'map',
      description:
        "Updates the user's live project map: the goal, tasks (merged by id; status todo, doing, done or blocked) and decisions. Send only what changed.",
      inputSchema: MAP_SCHEMA,
      isDeferred: false,
    })
    void $.ui.open({ id: PANE, title: 'Cockpit' })

    $.clock.every(STALL_CHECK_MS, () => {
      void (async () => {
        const held = await read($, config)
        const quietMs = (await $.clock.now()) - lastActivity
        if (!held.stuck || !isTurnRunning || hasStalled || quietMs < held.stallMinutes * 60_000) {
          return
        }
        hasStalled = true
        await raise(
          $,
          'stall',
          `cockpit: no tool activity for ${held.stallMinutes} minutes in a running turn. Claude may be stuck; interrupt with Esc if nothing is moving.`,
        )
      })()
    })

    return next(e)
  })

  on('command.run', { command: 'cockpit' }, async $ => {
    await $.ui.open({ id: PANE, title: 'Cockpit', focus: true })

    return { text: 'Cockpit opened.' }
  })

  on('prompt.compose', async ($, e, next) => {
    const composed = await next(e)
    const held = await read($, config)
    const sections = [...composed.sections]
    if (held.architect) {
      sections.push({ id: 'cockpit:architect', text: ARCHITECT_PROMPT, scope: 'session' })
    }
    if (held.map) {
      sections.push({ id: 'cockpit:map', text: MAP_PROMPT, scope: 'session' })
    }

    return { sections }
  })

  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind === 'plugin') {
      return next(e)
    }
    // The person spoke: the inspector may ask once more, and the first prompt
    // of a session carries the map kept from earlier ones.
    await update($, inspect, held => (held.nudges === 0 ? held : { ...held, nudges: 0 }))
    if (isBriefed) {
      return next(e)
    }
    isBriefed = true
    const held = await read($, config)
    const text = held.map ? brief(await read($, map)) : undefined

    return text === undefined ? next(e) : next({ ...e, context: [...(e.context ?? []), text] })
  })

  on('turn.start', async ($, e, next) => {
    loops.set(MAIN, freshLoop())
    isTurnRunning = true
    hasStalled = false
    lastActivity = await $.clock.now()

    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    const tool = String(e.tool)
    const args = e as unknown as Record<string, unknown>
    const now = await $.clock.now()

    if (tool === MAP_TOOL) {
      const held = await setMap($, before => mergeMap(before, args, now))
      const { done, total } = progress(held)

      return { result: `Map saved: ${done} of ${total} tasks done.` }
    }

    const held = await read($, config)
    const call: RecentCall = { id: e.tool_use_id, tool, preview: preview(args) }
    await update($, recent, list => [...list, call].slice(-40))
    if (held.map && tool === 'TodoWrite') {
      await setMap($, before => fromTodos(before, args.todos, now))
    }

    lastActivity = now
    const ran = await next(e)
    lastActivity = await $.clock.now()
    hasStalled = false
    if (ran.deny !== undefined) {
      return ran
    }

    const isError = ran.isError === true
    const file = editedFile(tool, args)
    if (!isError && file !== undefined && isUiFile(file)) {
      await update($, inspect, before =>
        before.pending.includes(file)
          ? before
          : { ...before, pending: [...before.pending, file].slice(-50) },
      )
    } else if (!isError && isVisualCheck(tool, args)) {
      await update($, inspect, before =>
        before.pending.length === 0 ? before : { ...before, pending: [], lastCheck: tool },
      )
    }

    if (!held.stuck) {
      return ran
    }
    const id = e.agentId ?? MAIN
    const loop = loops.get(id) ?? freshLoop()
    loops.set(id, loop)
    const seen = { tool, signature: signature(tool, args), isError }
    const found = observe(loop, file === undefined ? seen : { ...seen, file }, held)
    if (found === undefined) {
      return ran
    }
    await raise($, found.kind, found.text)

    return { ...ran, context: [...(ran.context ?? []), found.text] }
  })

  on('agent.spawn', async ($, e, next) => {
    const held = await read($, config)
    if (!held.architect || e.fork || e.workflow !== undefined || e.isTeammate === true) {
      return next(e)
    }
    const { level, why } = levelOf(e.description, e.prompt)
    const model = held.models[level]
    // A guess never overrides a model the caller chose; a tag does.
    if (model === 'inherit' || (why === 'guess' && e.model !== undefined)) {
      return next(e)
    }
    const route: Route = {
      at: await $.clock.now(),
      task: short(e.description, 50),
      level,
      model,
      why,
    }
    await update($, routes, list => [...list, route].slice(-30))

    return next({ ...e, model })
  })

  on('turn.complete', async ($, e, next) => {
    const held = await read($, config)
    const spent = e.usage
    if (spent !== undefined) {
      await update($, usage, totals => {
        const before = totals[spent.model] ?? { input: 0, output: 0, cached: 0, turns: 0 }

        return {
          ...totals,
          [spent.model]: {
            input: before.input + spent.input_tokens + spent.cache_creation_input_tokens,
            output: before.output + spent.output_tokens,
            cached: before.cached + spent.cache_read_input_tokens,
            turns: before.turns + 1,
          },
        }
      })
    }
    $.ui.status(held.meter ? meterLine(await read($, usage)) : undefined)

    if (e.agentId !== undefined) {
      loops.delete(e.agentId)

      return next(e)
    }
    isTurnRunning = false

    const owed = await read($, inspect)
    if (held.inspect && e.reason === 'answer' && owed.pending.length > 0 && owed.nudges === 0) {
      await update($, inspect, before => ({ ...before, nudges: before.nudges + 1 }))
      $.ui.toast('Cockpit: UI changed with no visual check. Asking for an inspection pass.')
      // Not awaited: the prompt's turn starts only once this one has ended.
      void $.prompt.submit({ text: checklist(owed.pending) }).catch(() => undefined)
    }

    return next(e)
  })

  on('session.compact', async ($, e, next) => {
    const result = await next(e)
    try {
      const held = await read($, config)
      const base = { at: await $.clock.now(), trigger: e.trigger, charsBefore: chars(e.messages) }
      const log = (entry: LedgerEntry) => update($, ledger, list => [...list, entry].slice(-20))
      if (result.skip !== undefined) {
        await log({ ...base, charsAfter: base.charsBefore, restored: 0, note: 'skipped' })

        return result
      }
      if (!held.guard) {
        await log({ ...base, charsAfter: chars(result.messages), restored: 0, note: 'guard off' })

        return result
      }

      const pinned = new Set((await read($, pins)).map(pin => pin.id))
      const keep = protectedIds(e.messages, pinned, held.rules)
      const fixed = restore(e.messages, result.messages, keep)
      await log({
        ...base,
        charsAfter: chars(fixed.messages),
        restored: fixed.restored,
        note: `${keep.size} protected`,
      })
      if (fixed.restored === 0) {
        return result
      }
      $.ui.toast(`Cockpit: put back ${fixed.restored} protected tool results after compaction.`)
      const { tokensAfter: _stale, ...kept } = result

      return { ...kept, messages: fixed.messages }
    } catch {
      return result
    }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const table = $.ui.resolve(e)
    const { Box, Text, Button } = table
    const Input = 'Input' in table ? table.Input : undefined
    const Select = 'Select' in table ? table.Select : undefined

    const shown = await read($, tab)
    const held = await read($, config)
    const width = Math.max(24, e.props.bodyColumns)
    const fit = (text: string) => short(text, width - 2)

    const toggle = (key: (typeof FEATURES)[number]['key'], label: string) => (
      <Button
        key={`toggle:${key}`}
        label={`${label}: ${held[key] ? 'ON' : 'off'}`}
        variant={held[key] ? 'primary' : 'secondary'}
        onPress={() => setConfig($, before => ({ ...before, [key]: !before[key] }))}
      />
    )

    const number = (
      key: 'repeatLimit' | 'errorLimit' | 'stallMinutes',
      label: string,
      values: readonly number[],
    ) =>
      Select === undefined ? (
        <Text>
          {label}: {String(held[key])}
        </Text>
      ) : (
        <Select
          key={`pick:${key}`}
          label={label}
          options={options(values)}
          value={String(held[key])}
          onSelect={value => setConfig($, before => ({ ...before, [key]: Number(value) }))}
        />
      )

    let body
    if (shown === 'home') {
      const owed = await read($, inspect)
      const seen = await read($, alerts)
      const { done, total } = progress(await read($, map))
      const totals = await read($, usage)
      body = (
        <Box flexDirection="column">
          {FEATURES.map(feature => (
            <Box flexDirection="column">
              {toggle(feature.key, feature.label)}
              <Text dimColor>{fit(`  ${feature.about}`)}</Text>
            </Box>
          ))}
          <Text> </Text>
          <Text bold>Now</Text>
          <Text>{`Tasks done: ${done} of ${total}`}</Text>
          <Text color={seen.length > 0 ? 'warning' : 'text'}>{`Stuck alerts: ${seen.length}`}</Text>
          <Text color={owed.pending.length > 0 ? 'warning' : 'text'}>
            {`UI files awaiting a visual check: ${owed.pending.length}`}
          </Text>
          {Object.keys(totals).map(model => (
            <Text dimColor>
              {fit(
                `${model}: ${thousands(totals[model]?.input ?? 0)} in, ${thousands(totals[model]?.output ?? 0)} out, ${thousands(totals[model]?.cached ?? 0)} cached, ${totals[model]?.turns ?? 0} turns`,
              )}
            </Text>
          ))}
        </Box>
      )
    } else if (shown === 'compact') {
      const pinned = await read($, pins)
      const calls = (await read($, recent)).filter(call => !pinned.some(pin => pin.id === call.id))
      const entries = await read($, ledger)
      body = (
        <Box flexDirection="column">
          {toggle('guard', 'Compact guard')}
          <Text dimColor>{fit('Pinned calls and rule matches are put back whole after compaction.')}</Text>
          <Button
            key="compact-now"
            label="Compact now"
            onPress={() => {
              void $.session.compact().catch(() => $.ui.toast('Cockpit: could not compact right now.'))
            }}
          />
          <Text> </Text>
          <Text bold>{`Pinned (${pinned.length})`}</Text>
          {pinned.length === 0 && <Text dimColor>Nothing pinned. Pin a call below.</Text>}
          {pinned.map(pin => (
            <Box>
              <Button
                key={`unpin:${pin.id}`}
                label="unpin"
                onPress={() => update($, pins, list => list.filter(one => one.id !== pin.id))}
              />
              <Text>{fit(` ${pin.tool} ${pin.preview}`)}</Text>
            </Box>
          ))}
          <Text> </Text>
          <Text bold>Always keep (rules)</Text>
          <Text dimColor>{fit('A rule is text found in a tool name or its arguments.')}</Text>
          {held.rules.map((rule, index) => (
            <Box>
              <Button
                key={`rule-off:${index}`}
                label="remove"
                onPress={() =>
                  setConfig($, before => ({
                    ...before,
                    rules: before.rules.filter(one => one !== rule),
                  }))
                }
              />
              <Text>{fit(` ${rule}`)}</Text>
            </Box>
          ))}
          {Input !== undefined && (
            <Input
              key="rule-new"
              label="Add rule"
              placeholder="npm test, git diff, src/auth"
              submitLabel="add"
              onSubmit={value => {
                const rule = value.trim()
                if (rule !== '') {
                  void setConfig($, before => ({
                    ...before,
                    rules: [...before.rules.filter(one => one !== rule), rule].slice(-30),
                  }))
                }
              }}
            />
          )}
          <Text> </Text>
          <Text bold>Recent tool calls</Text>
          {calls.length === 0 && <Text dimColor>None yet.</Text>}
          {calls
            .slice(-10)
            .reverse()
            .map(call => (
              <Box>
                <Button
                  key={`pin:${call.id}`}
                  label="pin"
                  onPress={() =>
                    update($, pins, list =>
                      list.some(one => one.id === call.id) ? list : [...list, call].slice(-50),
                    )
                  }
                />
                <Text>{fit(` ${call.tool} ${call.preview}`)}</Text>
              </Box>
            ))}
          <Text> </Text>
          <Text bold>Compaction ledger</Text>
          {entries.length === 0 && <Text dimColor>No compaction seen yet.</Text>}
          {entries
            .slice(-6)
            .reverse()
            .map(entry => (
              <Text color={entry.restored > 0 ? 'success' : 'text'}>
                {fit(
                  `${entry.trigger}: ${thousands(entry.charsBefore)} -> ${thousands(entry.charsAfter)} chars, restored ${entry.restored} (${entry.note})`,
                )}
              </Text>
            ))}
        </Box>
      )
    } else if (shown === 'map') {
      const plan = await read($, map)
      const { done, total } = progress(plan)
      const groups: readonly TaskStatus[] = ['doing', 'blocked', 'todo', 'done']
      const colors = { doing: 'suggestion', blocked: 'error', todo: 'text', done: 'success' } as const
      body = (
        <Box flexDirection="column">
          {toggle('map', 'Project map')}
          <Text bold>{fit(plan.goal === '' ? 'No goal set yet' : plan.goal)}</Text>
          <Text>{`[${bar(done, total, Math.min(30, width - 14))}] ${done}/${total}`}</Text>
          {groups.map(status => {
            const tasks = plan.tasks.filter(task => task.status === status)
            const view = status === 'done' ? tasks.slice(-8) : tasks

            return (
              <Box flexDirection="column">
                <Text> </Text>
                <Text bold color={colors[status]}>{`${status.toUpperCase()} (${tasks.length})`}</Text>
                {view.map(task => (
                  <Box flexDirection="column">
                    <Box>
                      <Button
                        key={`task:${task.id}`}
                        label={`-> ${NEXT_STATUS[task.status]}`}
                        dimColor
                        onPress={() =>
                          setMap($, before =>
                            mergeMap(
                              before,
                              { tasks: [{ id: task.id, status: NEXT_STATUS[task.status] }] },
                              before.updatedAt,
                            ),
                          )
                        }
                      />
                      <Text>{fit(` ${task.level ? `[${task.level}] ` : ''}${task.title}`)}</Text>
                    </Box>
                    {task.note !== undefined && <Text dimColor>{fit(`    ${task.note}`)}</Text>}
                  </Box>
                ))}
              </Box>
            )
          })}
          <Text> </Text>
          <Text bold>{`Decisions (${plan.decisions.length})`}</Text>
          {plan.decisions.slice(-8).map(decision => (
            <Text wrap="wrap">{`- ${decision}`}</Text>
          ))}
          <Text> </Text>
          {Input !== undefined && (
            <Input
              key="goal"
              label="Goal"
              value={plan.goal}
              submitLabel="set"
              onSubmit={value => {
                void setMap($, before => mergeMap(before, { goal: value }, before.updatedAt))
              }}
            />
          )}
          {Input !== undefined && (
            <Input
              key="task-new"
              label="Add task"
              placeholder="what needs doing"
              submitLabel="add"
              onSubmit={value => {
                const title = value.trim()
                if (title !== '') {
                  void setMap($, before =>
                    mergeMap(
                      before,
                      { tasks: [{ id: `me:${title.slice(0, 40)}`, title }] },
                      before.updatedAt,
                    ),
                  )
                }
              }}
            />
          )}
          <Button
            key="map-clear-done"
            label="Clear done tasks"
            dimColor
            onPress={() =>
              setMap($, before => ({
                ...before,
                tasks: before.tasks.filter(task => task.status !== 'done'),
              }))
            }
          />
        </Box>
      )
    } else if (shown === 'stuck') {
      const seen = await read($, alerts)
      body = (
        <Box flexDirection="column">
          {toggle('stuck', 'Stuck detector')}
          {number('repeatLimit', 'Same call repeats', [2, 3, 4, 5, 6])}
          {number('errorLimit', 'Errors in a row', [3, 4, 5, 6, 8])}
          {number('stallMinutes', 'Stall minutes', [2, 5, 10, 15])}
          <Text dimColor wrap="wrap">
            On a hit Claude is told to stop and change approach, and you get a toast.
          </Text>
          <Text> </Text>
          <Text bold>{`Alerts (${seen.length})`}</Text>
          {seen.length === 0 && <Text dimColor>None. Claude is moving.</Text>}
          {seen
            .slice(-8)
            .reverse()
            .map(alert => (
              <Text color="warning" wrap="wrap">{`${alert.kind}: ${short(alert.text.replace('cockpit: ', ''), 140)}`}</Text>
            ))}
          {seen.length > 0 && (
            <Button key="alerts-clear" label="Clear alerts" onPress={() => update($, alerts, () => [])} />
          )}
        </Box>
      )
    } else if (shown === 'inspect') {
      const owed = await read($, inspect)
      body = (
        <Box flexDirection="column">
          {toggle('inspect', 'Pixel inspector')}
          <Text dimColor wrap="wrap">
            When a turn ends with UI files edited and no screenshot taken since, Claude is sent
            back once to open the UI and check it.
          </Text>
          <Text> </Text>
          <Text bold color={owed.pending.length > 0 ? 'warning' : 'success'}>
            {owed.pending.length > 0
              ? `Awaiting a visual check (${owed.pending.length})`
              : 'Nothing awaiting a check'}
          </Text>
          {owed.pending.slice(-12).map(file => (
            <Text>{fit(`- ${file}`)}</Text>
          ))}
          {owed.lastCheck !== '' && <Text dimColor>{fit(`Last check: ${owed.lastCheck}`)}</Text>}
          {owed.pending.length > 0 && (
            <Box gap={1}>
              <Button
                key="inspect-now"
                label="Inspect now"
                variant="primary"
                onPress={() => {
                  void $.prompt.submit({ text: checklist(owed.pending) }).catch(() => undefined)
                }}
              />
              <Button
                key="inspect-done"
                label="I checked it myself"
                onPress={() => update($, inspect, before => ({ ...before, pending: [] }))}
              />
            </Box>
          )}
        </Box>
      )
    } else {
      const log = await read($, routes)
      body = (
        <Box flexDirection="column">
          {toggle('architect', 'Architect')}
          <Text dimColor wrap="wrap">
            The main session plans and reviews; each subagent runs on the model its task's
            difficulty picks. Takes effect from the next prompt.
          </Text>
          <Text> </Text>
          {LEVELS.map(level =>
            Select === undefined ? (
              <Text>{`${level}: ${held.models[level]}`}</Text>
            ) : (
              <Select
                key={`model:${level}`}
                label={`${level} tasks run on`}
                options={MODELS}
                value={held.models[level]}
                onSelect={value =>
                  setConfig($, before => ({
                    ...before,
                    models: { ...before.models, [level]: value },
                  }))
                }
              />
            ),
          )}
          <Text> </Text>
          <Text bold>{`Routed subagents (${log.length})`}</Text>
          {log.length === 0 && <Text dimColor>None yet.</Text>}
          {log
            .slice(-10)
            .reverse()
            .map(route => (
              <Text>{fit(`${route.level} -> ${route.model} (${route.why}): ${route.task}`)}</Text>
            ))}
        </Box>
      )
    }

    return (
      <Box flexDirection="column">
        <Box flexWrap="wrap" columnGap={1}>
          {TABS.map(one => (
            <Button
              key={`tab:${one.id}`}
              label={one.label}
              variant={one.id === shown ? 'primary' : 'secondary'}
              onPress={() => update($, tab, () => one.id)}
            />
          ))}
        </Box>
        <Text> </Text>
        {body}
      </Box>
    )
  })
}

