import type { SessionMessage } from 'claude-code'

type Messages = readonly SessionMessage[]

function idsOf(message: SessionMessage): string[] {
  return [
    ...message.toolUses.map(use => use.tool_use_id),
    ...(message.toolResults ?? []).map(result => result.tool_use_id),
  ]
}

/** A rule matches when it is found, ignoring case, in the tool's name and arguments. */
export function matchesRule(
  tool: string,
  input: unknown,
  rules: readonly string[],
): boolean {
  const haystack = `${tool} ${JSON.stringify(input) ?? ''}`.toLowerCase()

  return rules.some(rule => {
    const needle = rule.trim().toLowerCase()

    return needle !== '' && haystack.includes(needle)
  })
}

/** The tool calls a compaction must leave whole: the pinned ones and those a rule names. */
export function protectedIds(
  messages: Messages,
  pinned: ReadonlySet<string>,
  rules: readonly string[],
): Set<string> {
  const keep = new Set<string>()

  for (const message of messages) {
    for (const use of message.toolUses) {
      if (pinned.has(use.tool_use_id) || matchesRule(use.tool, use.input, rules)) {
        keep.add(use.tool_use_id)
      }
    }
  }

  return keep
}

function hasCall(messages: Messages, id: string): boolean {
  return messages.some(message => message.toolUses.some(use => use.tool_use_id === id))
}

/** How much of a call's result a transcript holds; -1 when it holds none. */
function resultLength(messages: Messages, id: string): number {
  let length = -1

  for (const message of messages) {
    for (const result of message.toolResults ?? []) {
      if (result.tool_use_id === id) {
        length = Math.max(length, result.text.length)
      }
    }
    for (const use of message.toolUses) {
      if (use.tool_use_id === id && use.text !== undefined) {
        length = Math.max(length, use.text.length)
      }
    }
  }

  return length
}

export function chars(messages: Messages): number {
  let total = 0

  for (const message of messages) {
    total += message.text.length
    for (const use of message.toolUses) {
      total += (JSON.stringify(use.input) ?? '').length
    }
    for (const result of message.toolResults ?? []) {
      total += result.text.length
    }
  }

  return total
}

/**
 * Puts back, whole and in their place, the protected tool calls a compaction
 * dropped or shortened. A call comes back with every message it is paired
 * with, so no tool_use is left without its tool_result.
 */
export function restore(
  before: Messages,
  after: Messages,
  keep: ReadonlySet<string>,
): { messages: SessionMessage[]; restored: number } {
  const damaged = [...keep].filter(
    id =>
      hasCall(before, id) &&
      (!hasCall(after, id) || resultLength(after, id) < resultLength(before, id)),
  )

  if (damaged.length === 0) {
    return { messages: [...after], restored: 0 }
  }

  const ids = new Set(damaged)
  const back = new Set<number>()
  let hasGrown = true

  while (hasGrown) {
    hasGrown = false
    before.forEach((message, index) => {
      if (back.has(index) || !idsOf(message).some(id => ids.has(id))) {
        return
      }
      back.add(index)
      hasGrown = true
      for (const id of idsOf(message)) {
        ids.add(id)
      }
    })
  }

  const byHandle = new Map<string, number>()
  const byId = new Map<string, number>()
  before.forEach((message, index) => {
    if (message.handle !== undefined) {
      byHandle.set(message.handle, index)
    }
    for (const id of idsOf(message)) {
      if (!byId.has(id)) {
        byId.set(id, index)
      }
    }
  })

  // Where each surviving message stood before; one the compaction wrote (a
  // summary) stands where the message ahead of it did.
  let last = -1
  const kept: { place: number; message: SessionMessage }[] = []
  for (const message of after) {
    const own = idsOf(message)
    if (own.some(id => ids.has(id))) {
      continue
    }
    const first = own[0]
    const place =
      (message.handle === undefined ? undefined : byHandle.get(message.handle)) ??
      (first === undefined ? undefined : byId.get(first)) ??
      last
    last = place
    kept.push({ place, message })
  }

  const order = [...back].sort((a, b) => a - b)
  const messages: SessionMessage[] = []
  let next = 0
  for (const { place, message } of kept) {
    for (; next < order.length && (order[next] ?? 0) < place; next += 1) {
      const original = before[order[next] ?? 0]
      if (original !== undefined) {
        messages.push(original)
      }
    }
    messages.push(message)
  }
  for (; next < order.length; next += 1) {
    const original = before[order[next] ?? 0]
    if (original !== undefined) {
      messages.push(original)
    }
  }

  return { messages, restored: damaged.length }
}

