const UI_FILE = /\.(tsx|jsx|vue|svelte|astro|html?|css|scss|sass|less|styl)$/i
const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])
const BROWSER = /browser|chrome|computer|playwright|puppeteer|devtools|preview/i
const CAPTURE = /screenshot|snapshot/i
const LOOKS = new Set(['screenshot', 'zoom'])

export function isUiFile(path: string): boolean {
  return UI_FILE.test(path)
}

/** The file an editing tool's call writes; undefined for any other call. */
export function editedFile(tool: string, args: Record<string, unknown>): string | undefined {
  if (!EDIT_TOOLS.has(tool)) {
    return undefined
  }
  const path = args.file_path ?? args.notebook_path

  return typeof path === 'string' ? path : undefined
}

/** Whether a call looked at rendered pixels: a screenshot or a zoom in a browser tool. */
export function isVisualCheck(tool: string, args: Record<string, unknown>): boolean {
  if (!BROWSER.test(tool)) {
    return false
  }

  return CAPTURE.test(tool) || (typeof args.action === 'string' && LOOKS.has(args.action))
}

export function checklist(files: readonly string[]): string {
  const shown = files.slice(0, 12).map(file => `- ${file}`)
  const more = files.length > 12 ? [`- and ${files.length - 12} more`] : []

  return [
    'Pixel inspection is owed before this work counts as done. These UI files changed and nothing rendered was looked at since:',
    ...shown,
    ...more,
    '',
    'Open the affected screens in a browser and take screenshots, then check each one against this list:',
    '1. Layout at desktop width and at a phone width (about 375px): nothing overflows, overlaps, or is clipped.',
    '2. Alignment and spacing: edges line up, gaps are consistent, nothing is jammed against a border.',
    '3. Text: readable size, enough contrast, no truncation that hides meaning, no placeholder copy left in.',
    '4. States: hover, focus, disabled, loading, empty and error where the change touches them.',
    '5. The browser console: no new errors or warnings.',
    '',
    'Fix what you find and look again. Then report what you checked and what you saw. If the UI cannot be run here, say so plainly instead of calling it verified.',
  ].join('\n')
}

