import type { Level, MapTask, ProjectMap, TaskStatus } from '../../types'

const MAX_TASKS = 200
const MAX_DECISIONS = 100
const MAX_TEXT = 300

const STATUSES: readonly string[] = ['todo', 'doing', 'done', 'blocked']
const LEVELS: readonly string[] = ['easy', 'medium', 'hard']

export const EMPTY_MAP: ProjectMap = { goal: '', tasks: [], decisions: [], updatedAt: 0 }

export const MAP_PROMPT = `# Project map (cockpit)

The user watches a live map of this project: its goal, its tasks and the decisions made. Keep it true with the mcp__cockpit__map tool: call it when you settle a plan, when a task starts, finishes or gets blocked, and when a decision is made that later work depends on. Send only what changed; tasks merge by id. Short titles, one line each.`

export const MAP_SCHEMA = {
  type: 'object',
  properties: {
    goal: { type: 'string', description: 'What the project is for, in one line.' },
    tasks: {
      type: 'array',
      description: 'Tasks to add or update, merged by id.',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string', description: 'A short stable id, like "auth-2".' },
          title: { type: 'string' },
          status: { type: 'string', enum: ['todo', 'doing', 'done', 'blocked'] },
          level: { type: 'string', enum: ['easy', 'medium', 'hard'] },
          note: { type: 'string', description: 'Why it is blocked, or what was found.' },
        },
        required: ['id'],
      },
    },
    decisions: {
      type: 'array',
      description: 'Decisions to record, one line each, with the reason.',
      items: { type: 'string' },
    },
  },
}

function line(value: unknown): string | undefined {
  return typeof value === 'string' && value.trim() !== ''
    ? value.trim().replace(/\s+/g, ' ').slice(0, MAX_TEXT)
    : undefined
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

/** Reads a stored or model-sent value as a map, dropping what is not one. */
export function asMap(value: unknown): ProjectMap {
  return isRecord(value) ? mergeMap(EMPTY_MAP, value, Number(value.updatedAt) || 0) : EMPTY_MAP
}

/** Merges a patch into the map: the goal replaces, tasks merge by id, decisions append. */
export function mergeMap(map: ProjectMap, patch: unknown, now: number): ProjectMap {
  if (!isRecord(patch)) {
    return map
  }

  const tasks = map.tasks.map(task => ({ ...task }))
  for (const raw of Array.isArray(patch.tasks) ? patch.tasks : []) {
    if (!isRecord(raw)) {
      continue
    }
    const id = line(raw.id)
    if (id === undefined) {
      continue
    }
    const known = tasks.find(task => task.id === id)
    const task: MapTask = known ?? { id, title: id, status: 'todo' }
    const title = line(raw.title)
    const note = line(raw.note)
    if (title !== undefined) {
      task.title = title
    }
    if (typeof raw.status === 'string' && STATUSES.includes(raw.status)) {
      task.status = raw.status as TaskStatus
    }
    if (typeof raw.level === 'string' && LEVELS.includes(raw.level)) {
      task.level = raw.level as Level
    }
    if (note !== undefined) {
      task.note = note
    }
    if (known === undefined) {
      tasks.push(task)
    }
  }

  const decisions = [...map.decisions]
  for (const raw of Array.isArray(patch.decisions) ? patch.decisions : []) {
    const decision = line(raw)
    if (decision !== undefined && !decisions.includes(decision)) {
      decisions.push(decision)
    }
  }

  return {
    goal: line(patch.goal) ?? map.goal,
    tasks: tasks.slice(-MAX_TASKS),
    decisions: decisions.slice(-MAX_DECISIONS),
    updatedAt: now,
  }
}

const TODO_STATUS: Record<string, TaskStatus> = {
  pending: 'todo',
  in_progress: 'doing',
  completed: 'done',
}

/** Mirrors a TodoWrite call's list into the map, each todo a task keyed by its text. */
export function fromTodos(map: ProjectMap, todos: unknown, now: number): ProjectMap {
  if (!Array.isArray(todos)) {
    return map
  }
  const tasks = todos.flatMap(todo => {
    const title = isRecord(todo) ? line(todo.content) : undefined
    const status = isRecord(todo) ? TODO_STATUS[String(todo.status)] : undefined

    return title === undefined ? [] : [{ id: `todo:${title.slice(0, 60)}`, title, status }]
  })

  return mergeMap(map, { tasks }, now)
}

export function progress(map: ProjectMap): { done: number; total: number } {
  return {
    done: map.tasks.filter(task => task.status === 'done').length,
    total: map.tasks.length,
  }
}

export function bar(done: number, total: number, width: number): string {
  const filled = total === 0 ? 0 : Math.round((done / total) * width)

  return `${'#'.repeat(filled)}${'-'.repeat(Math.max(0, width - filled))}`
}

/** The map as the model reads it when a session opens on a project that has one. */
export function brief(map: ProjectMap): string | undefined {
  if (map.goal === '' && map.tasks.length === 0 && map.decisions.length === 0) {
    return undefined
  }
  const { done, total } = progress(map)
  const open = map.tasks.filter(task => task.status !== 'done').slice(0, 30)

  return [
    'Project map kept by the cockpit plugin from earlier sessions (it may be stale; check before relying on it):',
    map.goal === '' ? undefined : `Goal: ${map.goal}`,
    `Tasks: ${done} of ${total} done.`,
    ...open.map(
      task => `- [${task.status}] ${task.id}: ${task.title}${task.note ? ` (${task.note})` : ''}`,
    ),
    map.decisions.length === 0 ? undefined : 'Decisions:',
    ...map.decisions.slice(-10).map(decision => `- ${decision}`),
  ]
    .filter(text => text !== undefined)
    .join('\n')
}

