import type { Level } from '../../types'

const TAG = /\[(easy|medium|hard)\]/i
const HARD =
  /architect|design|refactor|security|concurren|race condition|migrat|root cause|debug|performance|review/i
const EASY =
  /rename|typo|format|lint|list|find|search|locate|grep|read|summari[sz]e|comment|docstring|bump/i

export const ARCHITECT_PROMPT = `# Architect mode (cockpit)

This section is for the main session; a subagent ignores it.

Work as the architect: plan the work, split it into tasks, hand each task to a subagent with the Agent tool, and review what comes back before you accept it.

- Start each Agent call's description with its difficulty: [easy], [medium] or [hard]. The tag picks the subagent's model, so a mechanical task (a rename, a search, a small edit to a known spot) is [easy], ordinary feature work is [medium], and design, debugging or anything security-sensitive is [hard].
- Give each subagent everything it needs in its prompt: the goal, the files, what is already ruled out, and what done looks like.
- Review every result yourself: read the diff or the findings, check them against the plan, and send the task back or redo it when it falls short. Do not report a task done on the subagent's word alone.
- Keep small or tightly coupled work for yourself; delegate only what stands alone.`

/** A task's difficulty: its tag when the description or prompt carries one, else a guess. */
export function levelOf(
  description: string,
  prompt: string,
): { level: Level; why: 'tag' | 'guess' } {
  const tag = TAG.exec(description) ?? TAG.exec(prompt)
  if (tag?.[1] !== undefined) {
    return { level: tag[1].toLowerCase() as Level, why: 'tag' }
  }

  const text = `${description}\n${prompt}`
  if (HARD.test(text) || prompt.length > 2500) {
    return { level: 'hard', why: 'guess' }
  }
  if (EASY.test(text) && prompt.length < 800) {
    return { level: 'easy', why: 'guess' }
  }

  return { level: 'medium', why: 'guess' }
}

