import type { AlertKind } from '../../types'

export const THRASH_LIMIT = 6

const RESERVED = new Set(['tool', 'tool_use_id', 'agentId', 'consent'])

function stable(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map(stable).join(',')}]`
  }
  if (typeof value === 'object' && value !== null) {
    const record = value as Record<string, unknown>

    return `{${Object.keys(record)
      .sort()
      .map(key => `${JSON.stringify(key)}:${stable(record[key])}`)
      .join(',')}}`
  }

  return JSON.stringify(value) ?? 'undefined'
}

/** One call's identity: the tool and its arguments, whatever order they came in. */
export function signature(tool: string, args: Record<string, unknown>): string {
  const own: Record<string, unknown> = {}
  for (const key of Object.keys(args)) {
    if (!RESERVED.has(key)) {
      own[key] = args[key]
    }
  }

  return `${tool} ${stable(own)}`
}

export type Loop = {
  counts: Map<string, number>
  edits: Map<string, number>
  errors: number
}

export function freshLoop(): Loop {
  return { counts: new Map(), edits: new Map(), errors: 0 }
}

export type Observation = {
  tool: string
  signature: string
  isError: boolean
  /** The file the call edited, when it edited one. */
  file?: string
}

export type Limits = { repeatLimit: number; errorLimit: number }

export type Finding = { kind: AlertKind; text: string }

/** Counts one finished call into its loop and says when the loop looks stuck. */
export function observe(loop: Loop, seen: Observation, limits: Limits): Finding | undefined {
  const repeats = (loop.counts.get(seen.signature) ?? 0) + 1
  loop.counts.set(seen.signature, repeats)
  loop.errors = seen.isError ? loop.errors + 1 : 0

  if (repeats >= limits.repeatLimit && repeats % limits.repeatLimit === 0) {
    return {
      kind: 'loop',
      text: `cockpit: this exact ${seen.tool} call has now run ${repeats} times this turn with the same arguments. Repeating it will not change the outcome. Stop, say what you expected and what you got, then try a different approach or ask the user.`,
    }
  }

  if (loop.errors >= limits.errorLimit && loop.errors % limits.errorLimit === 0) {
    return {
      kind: 'errors',
      text: `cockpit: ${loop.errors} tool calls in a row have failed. Stop retrying. Read the errors again, name the root cause you believe in, and verify it with one cheap check before the next attempt; ask the user if you are blocked.`,
    }
  }

  if (seen.file !== undefined && !seen.isError) {
    const edits = (loop.edits.get(seen.file) ?? 0) + 1
    loop.edits.set(seen.file, edits)
    if (edits >= THRASH_LIMIT && edits % THRASH_LIMIT === 0) {
      return {
        kind: 'thrash',
        text: `cockpit: ${seen.file} has been edited ${edits} times this turn. That reads as thrashing. Re-read the whole file, decide the end state, and make it in one edit.`,
      }
    }
  }

  return undefined
}

