export type LedgerEntry = {
  at: number
  trigger: string
  charsBefore: number
  charsAfter: number
  restored: number
  note: string
}

export type TaskStatus = 'todo' | 'doing' | 'done' | 'blocked'

export type MapTask = {
  id: string
  title: string
  status: TaskStatus
  level?: Level
  note?: string
}

export type ProjectMap = {
  goal: string
  tasks: MapTask[]
  decisions: string[]
