  interface PluginState {
    cockpit: {
      tab: Tab
      config: Config
      pins: RecentCall[]
      recent: RecentCall[]
      ledger: LedgerEntry[]
      map: ProjectMap
      alerts: Alert[]
      routes: Route[]
      inspect: InspectState
